//#region src/data/coinbaseMarketDataProvider.ts
var CoinbaseMarketDataProvider = class {
	constructor() {
		this.name = "Coinbase Exchange";
		this.adapter = new CoinbaseAdapter();
	}
	async getCandles(symbol, timeframe, limit = 100) {
		if (!this.adapter.isSymbolSupported(symbol)) throw new Error(`[Coinbase] ${symbol} is not a supported spot asset on Coinbase.`);
		return this.adapter.getCandles(symbol, timeframe, limit);
	}
	async getLatestPrice(symbol) {
		return (await this.adapter.getLatestPrice(symbol)).price;
	}
	subscribeLive(symbol, timeframe, onCandle) {
		return this.adapter.subscribeLive(symbol, timeframe, (candle, isFinal) => {
			onCandle(candle, isFinal);
		});
	}
};
