	"BTC/USDT",
	"ETH/USDT",
	"BNB/USDT",
	"SOL/USDT",
	"XRP/USDT",
	"DOGE/USDT",
	"ADA/USDT",
	"AVAX/USDT",
	"LINK/USDT",
	"TRX/USDT"
